func (this *Btcturk) fetchOrderBookBody(ch chan AsyncResult[OrderBook], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pairSymbol": market["id"],
	}

	r1 := <-this.PublicGetOrderbook(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//     {
	//       "data": {
	//         "timestamp": 1618827901241,
	//         "bids": [
	//           [
	//             "460263.00",
	//             "0.04244000"
	//           ]
	//         ]
	//       }
	//     }
	var data map[string]any = this.SafeDictMap(response, "data", map[string]any{})
	var timestamp *int64 = this.SafeInteger(data, "timestamp")

	ch <- AsyncResult[OrderBook]{Value: OrderBookFromMap(this.ParseOrderBook(data, market["symbol"], timestamp, "bids", "asks", 0, 1))}
	return nil
}
func (this *Btcturk) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	//   {
	//     "pair": "BTCTRY",
	//     "pairNormalized": "BTC_TRY",
	//     "timestamp": 1618826361234,
	//     "last": 462485,
	//     "high": 473976,
	//     "low": 444201,
	//     "bid": 461928,
	//     "ask": 462485,
	//     "open": 456915,
	//     "volume": 917.41368645,
	//     "average": 462868.29574589,
	//     "daily": 5570,
	//     "dailyPercent": 1.22,
	//     "denominatorSymbol": "TRY",
	//     "numeratorSymbol": "BTC",
	//     "order": 1000
	//   }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "pair")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var timestamp *int64 = this.SafeInteger(ticker, "timestamp")
	var last *string = this.SafeString(ticker, "last")
	var open *string = this.SafeString(ticker, "open")
	var change *string = this.SafeString(ticker, "daily")
	var percentage *string = this.SafeString(ticker, "dailyPercent")
	var average *string = this.SafeString(ticker, "average")
	if (open != nil) && (last != nil) && !Precise.StringEq(open, "0") {
		// The reported daily fields can disagree with last - open.
		// Let safeTicker derive the unified change, percentage and average from these prices.
		change = nil
		percentage = nil
		average = nil
	}
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           this.SafeString(ticker, "bid"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "ask"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          open,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        change,
		"percentage":    percentage,
		"average":       average,
		"baseVolume":    this.SafeString(ticker, "volume"),
		"quoteVolume":   nil,
		"info":          ticker,
	}, marketResolved)
}

