func (this *Btcturk) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// fetchTrades
	//     {
	//       "pair": "BTCUSDT",
	//       "pairNormalized": "BTC_USDT",
	//       "numerator": "BTC",
	//       "denominator": "USDT",
	//       "date": "1618916879083",
	//       "tid": "637545136790672520",
	//       "price": "55774",
	//       "amount": "0.27917100",
	//       "side": "buy"
	//     }
	//
	// fetchMyTrades
	//     {
	//       "price": "56000",
	//       "numeratorSymbol": "BTC",
	//       "denominatorSymbol": "USDT",
	//       "orderType": "buy",
	//       "orderId": "2606935102",
	//       "id": "320874372",
	//       "timestamp": "1618916479593",
	//       "amount": "0.00020000",
	//       "fee": "0",
	//       "tax": "0"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger2(trade, "date", "timestamp")
	var id *string = this.SafeString2(trade, "tid", "id")
	var order *string = this.SafeString(trade, "orderId")
	var priceString *string = this.SafeString(trade, "price")
	var amountString *string = Precise.StringAbs(this.SafeString(trade, "amount"))
	var marketId *string = this.SafeString(trade, "pair")
	var symbol *string = this.SafeSymbol(marketId, market)
	var side *string = this.SafeString2(trade, "side", "orderType")
	var fee map[string]any = nil
	var feeAmountString *string = this.SafeString(trade, "fee")
	if feeAmountString != nil {
		var feeCurrency *string = this.SafeString(trade, "denominatorSymbol")
		fee = map[string]any{
			"cost":     Precise.StringAbs(feeAmountString),
			"currency": this.SafeCurrencyCode(feeCurrency),
		}
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           id,
		"order":        order,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"type":         nil,
		"side":         side,
		"takerOrMaker": nil,
		"price":        priceString,
		"amount":       amountString,
		"cost":         nil,
		"fee":          fee,
	}, market)
}

