/**
 * @method
 * @name btcturk#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://docs.btcturk.com/public-endpoints/get-kline-data
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Btcturk) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]OHLCV] {
	ch := make(chan AsyncResult[[]OHLCV], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Btcturk) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1h")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol":     market["id"],
		"resolution": this.SafeString(this.Timeframes, timeframe, timeframe),
	}
	var until *int64 = this.SafeInteger(params, "until", this.Milliseconds())
	var untilSeconds int64 = this.ParseToInt((float64(*until) / 1000))
	request["to"] = untilSeconds
	if since != nil {
		request["from"] = this.ParseToInt(float64(*since) / 1000)
	}
	var limitResolved any = nil
	if limit != nil {
		limitResolved = limit
		if *limit > 11000 {
			limitResolved = 11000 // max 11000 candles diapason can be covered
		}
	} else if since == nil {
		limitResolved = 100 // default value
	}
	if (limit != nil) || (since == nil) {
		if timeframe == "1y" {
			panic(BadRequest(this.Id + " fetchOHLCV () does not accept a limit parameter when timeframe == \"1y\""))
		}
		var seconds int64 = this.ParseTimeframe(timeframe)
		var limitCount int64 = func() int64 {
			if limit == nil {
				return 100
			}
			return min(*limit, 11000)
		}()
		var limitSeconds int64 = this.ParseToInt(seconds * (limitCount - 1))
		if since != nil {
			var sinceSeconds int64 = this.ParseToInt(float64(*since) / 1000)
			var to int64 = sinceSeconds + limitSeconds
			if to < untilSeconds {
				request["to"] = to
			}
		} else {
			request["from"] = 0 - limitSeconds
		}
	}

	r1 := <-this.GraphGetKlinesHistory(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//    {
	//        "s": "ok",
	//        "t": [
	//          1661990400,
	//          1661990520,
	//          ...
	//        ],
	//        "h": [
	//          368388.0,
	//          369090.0,
	//          ...
	//        ],
	//        "o": [
	//          368388.0,
	//          368467.0,
	//          ...
	//        ],
	//        "l": [
	//          368388.0,
	//          368467.0,
	//          ...
	//        ],
	//        "c": [
	//          368388.0,
	//          369090.0,
	//          ...
	//        ],
	//        "v": [
	//          0.00035208,
	//          0.2972395,
	//          ...
	//        ]
	//    }
	//
	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(response, market, timeframe, since, limitResolved))}
	return nil
}
func (this *Btcturk) ParseOHLCVs(ohlcvs any, optionalArgs ...any) []any {
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var timeframe string = GetArgString(optionalArgs, 1, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 3, nil)
	_ = limit
	var tail bool = GetArgBool(optionalArgs, 4, false)
	_ = tail
	var results []any = []any{}
	var timestamp []any = SafeListTyped(ohlcvs, "t")
	var high []any = SafeListTyped(ohlcvs, "h")
	var open []any = SafeListTyped(ohlcvs, "o")
	var low []any = SafeListTyped(ohlcvs, "l")
	var close []any = SafeListTyped(ohlcvs, "c")
	var volume []any = SafeListTyped(ohlcvs, "v")
	for i := 0; i < len(timestamp); i++ {
		var ohlcv map[string]any = map[string]any{
			"timestamp": this.SafeInteger(timestamp, i),
			"high":      this.SafeNumber(high, i),
			"open":      this.SafeNumber(open, i),
			"low":       this.SafeNumber(low, i),
			"close":     this.SafeNumber(close, i),
			"volume":    this.SafeNumber(volume, i),
		}
		results = append(results, OHLCVToList(this.ParseOHLCV(ohlcv, market)))
	}
	var sorted []any = this.SortBy(results, 0)
	return this.FilterBySinceLimit(sorted, since, limit, 0, tail)
}

/**
 * @method
 * @name btcturk#createOrder
 * @description create a trade order
 * @see https://docs.btcturk.com/private-endpoints/submit-order
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Btcturk) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Btcturk) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"orderType":   side,
		"orderMethod": typeVar,
		"pairSymbol":  market["id"],
		"quantity":    this.AmountToPrecision(symbol, amount),
	}
	if typeVar != "market" {
		request["price"] = this.PriceToPrecision(symbol, price)
	}
	if _, ok := params["clientOrderId"]; ok {
		request["newClientOrderId"] = params["clientOrderId"]
	} else if _, ok := params["newClientOrderId"]; !ok {
		request["newClientOrderId"] = this.Uuid()
	}

	r1 := <-this.PrivatePostOrder(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var data map[string]any = this.SafeDictMap(response, "data", map[string]any{})

	ch <- AsyncResult[Order]{Value: this.ParseOrder(data, market)}
	return nil
}

